'use client';
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, Bot, Code2, AlertCircle, Quote, Loader2, CheckCircle, XCircle, ArrowRight } from 'lucide-react';
import { cn } from '@/lib/utils';

import { SubmissionSuccessModal } from './dojo/SubmissionSuccessModal';
import { toast } from 'sonner';

export function AiSenpai() {
    const [problemName, setProblemName] = useState('');
    const [userCode, setUserCode] = useState('');
    const [hint, setHint] = useState<{ flaw: string; hint: string; confidence: number } | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [verdictResult, setVerdictResult] = useState<any>(null);

    // Verify CF Account Submission
    const handleVerifyCF = async () => {
        if (!problemName.trim()) {
            setError("Please enter a Problem ID (e.g. 1385C) to verify.");
            return;
        }
        setLoading(true);
        setError('');
        setVerdictResult(null);
        const toastId = toast.loading("Checking your Codeforces submissions...");

        try {
            const res = await fetch('/api/dojo/verify-cf', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ problemName })
            });

            const data = await res.json();

            if (!res.ok) throw new Error(data.error || "Verification failed");

            if (data.verdict === "NOT_FOUND") {
                toast.error("Not Found", { id: toastId, description: data.message });
                setError(data.message);
                return;
            }

            // Map CF verdict to our internal format
            const result = {
                verdict: data.verdict === "OK" ? "ACCEPTED" : data.verdict,
                reason: data.verdict === "OK" ? "Verified on Codeforces: Accepted!" : `Fails on Test ${data.testCount}`,
                cases_passed: data.passed ? 100 : data.testCount,
                total_cases: 100,
                source: "CF_ACCOUNT"
            };

            setVerdictResult(result);
            toast.success("Found Submission!", { id: toastId });

            if (result.verdict === "ACCEPTED") {
                setShowSuccessModal(true);
            }
        } catch (e: any) {
            toast.error("Verification Error", { id: toastId, description: e.message });
            // Check if user needs to link account
            if (e.message.includes("Link your Codeforces")) {
                setError("You need to link your Codeforces account in settings first.");
            }
        } finally {
            setLoading(false);
        }
    };

    // Real AI Judge Handler
    const handleSubmit = async () => {
        console.log("Submit clicked");
        if (!userCode.trim() || !problemName.trim()) {
            setError("Please provide problem and code.");
            return;
        }
        setLoading(true);
        setError('');
        setVerdictResult(null); // Clear previous

        const toastId = toast.loading("Queuing submission...");

        try {
            // Artificial delay for "Realism" (Wait for Judge Node)
            await new Promise(r => setTimeout(r, 800));
            toast.loading("Running on Test Cases 1...10", { id: toastId });

            const res = await fetch('/api/dojo/judge', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    problemName,
                    problemStatement: problemName,
                    userCode,
                    language: "cpp"
                })
            });

            console.log("Judge Response Status:", res.status);

            if (!res.ok) {
                const text = await res.text();
                throw new Error(`Server Error: ${res.status} ${text.slice(0, 50)}`);
            }

            const verdict = await res.json();
            console.log("Verdict:", verdict);
            setVerdictResult(verdict);

            if (verdict.verdict === 'ACCEPTED') {
                toast.success("Verdict: ACCEPTED", { id: toastId, description: `Passed ${verdict.cases_passed}/100 tests` });
                setShowSuccessModal(true);
            } else {
                toast.error(`Verdict: ${verdict.verdict}`, {
                    id: toastId,
                    description: verdict.reason || "Failed on hidden test cases.",
                    duration: 5000
                });
            }
        } catch (e: any) {
            console.error("Submit Error:", e);
            toast.error("Judge Error", { id: toastId, description: e.message || "Could not reach server." });
            setVerdictResult({ verdict: 'ERROR', reason: e.message || "Judge connection failed." });
        } finally {
            setLoading(false);
        }
    };

    const handleAskSenpai = async () => {
        if (!userCode.trim() || !problemName.trim()) {
            setError("Please provide both the problem name and your code.");
            return;
        }

        setLoading(true);
        setError('');
        setHint(null);

        try {
            const res = await fetch('/api/ai/hint', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    problemName,
                    problemStatement: problemName, // MVP: Just passing name/url as context
                    userCode,
                    language: "cpp" // Default assume C++, can add selector later
                })
            });

            const data = await res.json();
            if (data.error) throw new Error(data.error);
            setHint(data);
        } catch (err: any) {
            setError(err.message || "Senpai is busy. Try again later.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto space-y-6">
            {/* Input Section */}
            <div className="bg-zinc-900/50 border border-zinc-800 rounded-2xl p-6 backdrop-blur-sm">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-indigo-500/10 rounded-lg">
                        <Bot className="text-indigo-400" size={24} />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-white">AI Senpai <span className="text-xs ml-2 bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded-full border border-indigo-500/30">Beta</span></h2>
                        <p className="text-zinc-400 text-sm">Paste your incorrect code. I'll find the bug without spoiling the answer.</p>
                    </div>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="text-xs uppercase font-bold text-zinc-500 tracking-wider mb-2 block">Problem ID / URL <span className="text-indigo-400 ml-2">(e.g. 1700A)</span></label>
                        <input
                            value={problemName}
                            onChange={(e) => setProblemName(e.target.value)}
                            placeholder="Enter Codeforces ID (e.g., 1500A) for Real Tests"
                            className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 text-white focus:ring-2 focus:ring-indigo-500 focus:outline-none transition placeholder:text-zinc-700 font-mono text-sm"
                        />
                    </div>

                    <div>
                        <label className="text-xs uppercase font-bold text-zinc-500 tracking-wider mb-2 block">Your Code</label>
                        <textarea
                            value={userCode}
                            onChange={(e) => setUserCode(e.target.value)}
                            placeholder="// Paste your C++ code here..."
                            className="w-full h-64 bg-zinc-950 border border-zinc-800 rounded-lg p-4 text-xs font-mono text-zinc-300 focus:ring-2 focus:ring-indigo-500 focus:outline-none transition resize-none leading-relaxed"
                            spellCheck={false}
                        />
                    </div>

                    {error && (
                        <div className="p-3 bg-red-900/20 border border-red-800/50 rounded-lg flex items-center gap-2 text-red-400 text-sm">
                            <AlertCircle size={16} />
                            {error}
                        </div>
                    )}

                    <div className="grid grid-cols-2 gap-3">
                        <button
                            onClick={handleAskSenpai}
                            disabled={loading}
                            className="bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-xl transition flex items-center justify-center gap-2"
                        >
                            {loading ? <Loader2 className="animate-spin" size={18} /> : <Sparkles size={18} />}
                            Get Hint
                        </button>
                        <button
                            onClick={handleSubmit}
                            disabled={loading}
                            className="bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-xl transition flex items-center justify-center gap-2"
                        >
                            <Code2 size={18} /> Submit
                        </button>
                    </div>

                    <div className="flex justify-center">
                        <button
                            onClick={handleVerifyCF}
                            disabled={loading}
                            className="text-xs text-zinc-500 hover:text-indigo-400 underline decoration-dotted transition flex items-center gap-1"
                        >
                            Or verify a submission you made on Codeforces directly <ArrowRight size={12} />
                        </button>
                    </div>

                    <AnimatePresence>
                        {verdictResult && (
                            <motion.div
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: "auto" }}
                                exit={{ opacity: 0, height: 0 }}
                                className={cn(
                                    "rounded-xl p-4 border flex items-start gap-4 overflow-hidden",
                                    verdictResult.verdict === 'ACCEPTED'
                                        ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-200"
                                        : "bg-red-500/10 border-red-500/20 text-red-200"
                                )}
                            >
                                <div className={cn("p-2 rounded-full", verdictResult.verdict === 'ACCEPTED' ? "bg-emerald-500/20" : "bg-red-500/20")}>
                                    {verdictResult.verdict === 'ACCEPTED' ? <CheckCircle size={24} /> : <XCircle size={24} />}
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg">{verdictResult.verdict}</h3>
                                    <p className="text-sm opacity-80 mt-1">{verdictResult.reason}</p>
                                    {verdictResult.cases_passed !== undefined && (
                                        <div className="mt-2 flex gap-2">
                                            <div className="text-xs font-mono bg-black/20 px-2 py-1 rounded inline-block">
                                                Test Cases: {verdictResult.cases_passed}/{verdictResult.total_cases}
                                            </div>
                                            {verdictResult.source === 'SCRAPER' && (
                                                <div className="text-xs font-bold bg-indigo-500/20 text-indigo-300 px-2 py-1 rounded border border-indigo-500/30 flex items-center gap-1">
                                                    <Sparkles size={10} /> Real Tests (CF)
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            {/* Response Section */}
            <AnimatePresence>
                {hint && (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="bg-gradient-to-br from-indigo-900/20 to-violet-900/20 border border-indigo-500/30 rounded-2xl p-6 relative overflow-hidden"
                    >
                        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500" />

                        <div className="flex items-start gap-4">
                            <div className="p-3 bg-indigo-500/20 rounded-full">
                                <Quote className="text-indigo-300" size={24} />
                            </div>
                            <div className="space-y-4">
                                <div>
                                    <h3 className="text-indigo-200 font-bold text-lg mb-1">Senpai's Analysis</h3>
                                    <p className="text-zinc-400 text-sm italic">"{hint.flaw}"</p>
                                </div>

                                <div className="bg-zinc-950/50 p-4 rounded-xl border border-indigo-500/20">
                                    <p className="text-white leading-relaxed">
                                        {hint.hint}
                                    </p>
                                </div>

                                <div className="flex items-center gap-2 text-xs text-indigo-400/60 font-mono">
                                    <span>CONFIDENCE SCORE: {Math.round(hint.confidence * 100)}%</span>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <SubmissionSuccessModal
                isOpen={showSuccessModal}
                onClose={() => setShowSuccessModal(false)}
                onNextProblem={() => {
                    setShowSuccessModal(false);
                    setUserCode("// New Problem\n");
                    setProblemName("");
                }}
                userCode={userCode}
                problemTitle={problemName}
                problemDescription={problemName} // MVP: Passing info for context
            />
        </div>
    );
}

// Simple Mock Verdict for Demo
const mockJudge = async () => {
    await new Promise(r => setTimeout(r, 1500));
    return Math.random() > 0.3; // 70% chance of WRONG ANSWER for realism? Or force accept?
    // For demo of "Success Modal", we force accept if code > 10 chars
    return true;
};
